CREATE TABLE project_members(project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES user(id), role TEXT NOT NULL CHECK(role IN ('viewer','editor','reviewer')), added_by TEXT NOT NULL REFERENCES user(id), created_at TEXT NOT NULL, PRIMARY KEY(project_id,user_id));
CREATE INDEX member_user ON project_members(user_id,project_id);
CREATE TABLE missions(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, question TEXT NOT NULL, scope TEXT NOT NULL, acceptance TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused','completed','cancelled')), created_by TEXT NOT NULL REFERENCES user(id), revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(id,project_id));
CREATE TABLE mission_tasks(id TEXT PRIMARY KEY, mission_id TEXT NOT NULL, project_id TEXT NOT NULL, title TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('search','extract','compare','counter','verify','review','publish','compute','ocr','manual')), executor TEXT NOT NULL CHECK(executor IN ('builtin','model','external','human')), assignee TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'blocked' CHECK(status IN ('blocked','ready','queued','running','succeeded','review','accepted','rejected','failed','uncertain','cancelled','stale')), input TEXT NOT NULL CHECK(json_valid(input)), result TEXT CHECK(result IS NULL OR json_valid(result)), error TEXT, attempt INTEGER NOT NULL DEFAULT 0, lease_hash TEXT, review_token TEXT, lease_until TEXT, claimed_by TEXT, cost_units INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(mission_id,project_id) REFERENCES missions(id,project_id), UNIQUE(id,mission_id), UNIQUE(id,project_id));
CREATE INDEX mission_task_dispatch ON mission_tasks(status,updated_at);
CREATE INDEX mission_task_project ON mission_tasks(project_id,mission_id);
CREATE TABLE task_dependencies(task_id TEXT NOT NULL, depends_on TEXT NOT NULL, mission_id TEXT NOT NULL, PRIMARY KEY(task_id,depends_on), FOREIGN KEY(task_id,mission_id) REFERENCES mission_tasks(id,mission_id), FOREIGN KEY(depends_on,mission_id) REFERENCES mission_tasks(id,mission_id), CHECK(task_id<>depends_on));
CREATE TABLE task_inputs(task_id TEXT NOT NULL REFERENCES mission_tasks(id), version_id TEXT NOT NULL REFERENCES source_versions(id), PRIMARY KEY(task_id,version_id));
CREATE TABLE task_events(id INTEGER PRIMARY KEY AUTOINCREMENT, task_id TEXT REFERENCES mission_tasks(id), mission_id TEXT NOT NULL REFERENCES missions(id), actor TEXT NOT NULL, kind TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX events_mission ON task_events(mission_id,id);
CREATE TABLE task_reviews(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES mission_tasks(id), attempt INTEGER NOT NULL, reviewer TEXT NOT NULL REFERENCES user(id), decision TEXT NOT NULL CHECK(decision IN ('accepted','rejected')), reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE project_comments(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), target_id TEXT NOT NULL, author TEXT NOT NULL REFERENCES user(id), body TEXT NOT NULL, resolved INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE agent_credentials(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), owner_id TEXT NOT NULL REFERENCES user(id), label TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, scopes TEXT NOT NULL CHECK(json_valid(scopes)), expires_at TEXT NOT NULL, revoked_at TEXT, last_used_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE source_pages(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), source_id TEXT NOT NULL REFERENCES sources(id), version_id TEXT NOT NULL REFERENCES source_versions(id), page INTEGER NOT NULL, text TEXT NOT NULL, normalized TEXT NOT NULL, content_hash TEXT NOT NULL, language TEXT NOT NULL DEFAULT '', year_start INTEGER, year_end INTEGER, UNIQUE(version_id,page));
CREATE INDEX page_project ON source_pages(project_id,source_id,version_id);
CREATE VIRTUAL TABLE page_fts USING fts5(page_id UNINDEXED,project_id UNINDEXED,source_id UNINDEXED,version_id UNINDEXED,page UNINDEXED,text,normalized,tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER page_search_insert AFTER INSERT ON source_pages BEGIN INSERT INTO page_fts(page_id,project_id,source_id,version_id,page,text,normalized) VALUES(new.id,new.project_id,new.source_id,new.version_id,new.page,new.text,new.normalized); END;
CREATE TRIGGER page_search_delete AFTER DELETE ON source_pages BEGIN DELETE FROM page_fts WHERE page_id=old.id; END;
CREATE TABLE search_aliases(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), term TEXT NOT NULL, variants TEXT NOT NULL CHECK(json_valid(variants)), basis TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES user(id), created_at TEXT NOT NULL, UNIQUE(project_id,term));
CREATE TABLE artifacts(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), mission_id TEXT REFERENCES missions(id), task_id TEXT REFERENCES mission_tasks(id), title TEXT NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL CHECK(json_valid(body)), source_versions TEXT NOT NULL CHECK(json_valid(source_versions)), sha256 TEXT NOT NULL, license TEXT NOT NULL, created_by TEXT NOT NULL, derived_from TEXT REFERENCES artifacts(id), supersedes TEXT REFERENCES artifacts(id), created_at TEXT NOT NULL, UNIQUE(task_id,sha256));
CREATE TABLE artifact_reviews(artifact_id TEXT NOT NULL REFERENCES artifacts(id), reviewer TEXT NOT NULL REFERENCES user(id), status TEXT NOT NULL CHECK(status IN ('accepted','rejected','needs_review')), reason TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(artifact_id,reviewer,created_at));
CREATE TABLE artifact_dependencies(artifact_id TEXT NOT NULL REFERENCES artifacts(id), depends_on TEXT NOT NULL REFERENCES artifacts(id), PRIMARY KEY(artifact_id,depends_on), CHECK(artifact_id<>depends_on));
CREATE TABLE artifact_grants(artifact_id TEXT NOT NULL REFERENCES artifacts(id), project_id TEXT NOT NULL REFERENCES projects(id), granted_by TEXT NOT NULL REFERENCES user(id), created_at TEXT NOT NULL, PRIMARY KEY(artifact_id,project_id));
CREATE TABLE project_snapshots(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, manifest TEXT NOT NULL CHECK(json_valid(manifest)), sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES user(id), created_at TEXT NOT NULL);
CREATE TABLE research_branches(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, base_snapshot TEXT NOT NULL REFERENCES project_snapshots(id), changes TEXT NOT NULL CHECK(json_valid(changes)), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','merged','rejected')), revision INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES user(id), created_at TEXT NOT NULL, merge_token TEXT);
CREATE TABLE branch_reviews(id TEXT PRIMARY KEY, branch_id TEXT NOT NULL REFERENCES research_branches(id), reviewer TEXT NOT NULL REFERENCES user(id), decision TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE entities(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), kind TEXT NOT NULL CHECK(kind IN ('person','place','organization','event')), name TEXT NOT NULL, aliases TEXT NOT NULL CHECK(json_valid(aliases)), date_start INTEGER, date_end INTEGER, latitude REAL, longitude REAL, evidence TEXT NOT NULL CHECK(json_valid(evidence)), status TEXT NOT NULL CHECK(status IN ('candidate','confirmed','rejected')), canonical_id TEXT REFERENCES entities(id), revision INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES user(id), created_at TEXT NOT NULL);
CREATE TABLE entity_relations(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), from_id TEXT NOT NULL REFERENCES entities(id), to_id TEXT NOT NULL REFERENCES entities(id), kind TEXT NOT NULL, basis TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE evaluation_runs(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, dataset TEXT NOT NULL, config TEXT NOT NULL CHECK(json_valid(config)), metrics TEXT NOT NULL CHECK(json_valid(metrics)), results TEXT NOT NULL CHECK(json_valid(results)), created_by TEXT NOT NULL REFERENCES user(id), created_at TEXT NOT NULL);
CREATE TABLE model_policies(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), task_kind TEXT NOT NULL, model_id TEXT NOT NULL REFERENCES model_connections(id), input_rate REAL NOT NULL CHECK(input_rate>=0), output_rate REAL NOT NULL CHECK(output_rate>=0), max_output INTEGER NOT NULL DEFAULT 4096, created_at TEXT NOT NULL, UNIQUE(owner_id,task_kind));
CREATE TABLE model_checks(id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES model_connections(id), owner_id TEXT NOT NULL REFERENCES user(id), status TEXT NOT NULL, latency_ms INTEGER NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE source_origins(source_id TEXT PRIMARY KEY REFERENCES sources(id), provider TEXT NOT NULL, external_id TEXT NOT NULL, url TEXT NOT NULL, license TEXT NOT NULL, retrieved_at TEXT NOT NULL, content_hash TEXT NOT NULL, metadata TEXT NOT NULL CHECK(json_valid(metadata)));
CREATE TABLE cloud_connections(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), provider TEXT NOT NULL CHECK(provider IN ('google','microsoft')), encrypted_token TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(owner_id,provider));
CREATE TABLE oauth_states(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), provider TEXT NOT NULL, verifier TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE ingestion_items(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), owner_id TEXT NOT NULL REFERENCES user(id), provider TEXT NOT NULL, external_id TEXT NOT NULL, revision TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL, source_id TEXT REFERENCES sources(id), error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,provider,external_id,revision));
CREATE INDEX ingestion_dispatch ON ingestion_items(status,updated_at);
ALTER TABLE research_jobs ADD COLUMN locale TEXT NOT NULL DEFAULT 'zh-CN';
CREATE TRIGGER invalidate_task_source AFTER INSERT ON source_versions WHEN new.revision>1 BEGIN UPDATE mission_tasks SET status='stale',revision=revision+1,updated_at=new.created_at WHERE id IN (SELECT ti.task_id FROM task_inputs ti JOIN source_versions v ON v.id=ti.version_id WHERE v.source_id=new.source_id AND v.id<>new.id) AND status IN ('accepted','succeeded','review','ready','blocked'); END;
CREATE TRIGGER immutable_artifact_update BEFORE UPDATE ON artifacts BEGIN SELECT RAISE(ABORT,'Artifacts are immutable'); END;
CREATE TRIGGER immutable_artifact_delete BEFORE DELETE ON artifacts BEGIN SELECT RAISE(ABORT,'Artifacts are immutable'); END;
CREATE TABLE task_attempts(task_id TEXT NOT NULL REFERENCES mission_tasks(id), attempt INTEGER NOT NULL, actor TEXT NOT NULL, input TEXT NOT NULL CHECK(json_valid(input)), dependencies TEXT NOT NULL CHECK(json_valid(dependencies)), result TEXT CHECK(result IS NULL OR json_valid(result)), status TEXT NOT NULL, created_at TEXT NOT NULL, finished_at TEXT, PRIMARY KEY(task_id,attempt));
